    def countDistinctPoints(self, s: str, k: int) -> int:
        # Move directions: U, D, L, R
        delta = {'U': (0, 1), 'D': (0, -1), 'L': (-1, 0), 'R': (1, 0)}
        n = len(s)

        # Total displacement of entire string
        total_dx = sum(delta[c][0] for c in s)
        total_dy = sum(delta[c][1] for c in s)

        # When removing a substring s[i..i+k-1], the final position is (total_dx - win_dx, total_dy - win_dy)
        # Distinct final points corresponds to distinct window displacements of length k
        cur_dx = sum(delta[s[i]][0] for i in range(k))
        cur_dy = sum(delta[s[i]][1] for i in range(k))
        distinct_displacements = {(cur_dx, cur_dy)}

        for i in range(k, n):
            cur_dx += delta[s[i]][0] - delta[s[i - k]][0]
            cur_dy += delta[s[i]][1] - delta[s[i - k]][1]
            distinct_displacements.add((cur_dx, cur_dy))

        return len(distinct_displacements)
