#include <string>
#include <vector>
#include <set>

class Solution {
public:
    int countDistinctPoints(std::string s, int k) {
        int n = s.size();
        auto get_d = [](char c) -> std::pair<int, int> {
            if (c == 'U') return {0, 1};
            if (c == 'D') return {0, -1};
            if (c == 'L') return {-1, 0};
            return {1, 0};
        };

        int cur_x = 0, cur_y = 0;
        for (int i = 0; i < k; ++i) {
            auto [dx, dy] = get_d(s[i]);
            cur_x += dx;
            cur_y += dy;
        }

        std::set<std::pair<int, int>> distinct;
        distinct.insert({cur_x, cur_y});

        for (int i = k; i < n; ++i) {
            auto [add_x, add_y] = get_d(s[i]);
            auto [sub_x, sub_y] = get_d(s[i - k]);
            cur_x += add_x - sub_x;
            cur_y += add_y - sub_y;
            distinct.insert({cur_x, cur_y});
        }
        return distinct.size();
    }
};

import java.util.*;

class Solution {
    public int countDistinctPoints(String s, int k) {
        int n = s.length();
        int curX = 0, curY = 0;
        for (int i = 0; i < k; i++) {
            int[] d = getDelta(s.charAt(i));
            curX += d[0];
            curY += d[1];
        }

        Set<String> distinct = new HashSet<>();
        distinct.add(curX + "," + curY);

        for (int i = k; i < n; i++) {
            int[] add = getDelta(s.charAt(i));
            int[] sub = getDelta(s.charAt(i - k));
            curX += add[0] - sub[0];
            curY += add[1] - sub[1];
            distinct.add(curX + "," + curY);
        }
        return distinct.size();
    }

    private int[] getDelta(char c) {
        if (c == 'U') return new int[]{0, 1};
        if (c == 'D') return new int[]{0, -1};
        if (c == 'L') return new int[]{-1, 0};
        return new int[]{1, 0};
    }
}

var countDistinctPoints = function(s, k) {
    const n = s.length;
    function getDelta(c) {
        if (c === 'U') return [0, 1];
        if (c === 'D') return [0, -1];
        if (c === 'L') return [-1, 0];
        return [1, 0];
    }

    let curX = 0, curY = 0;
    for (let i = 0; i < k; i++) {
        const [dx, dy] = getDelta(s[i]);
        curX += dx;
        curY += dy;
    }

    const distinct = new Set();
    distinct.add(`${curX},${curY}`);

    for (let i = k; i < n; i++) {
        const [addX, addY] = getDelta(s[i]);
        const [subX, subY] = getDelta(s[i - k]);
        curX += addX - subX;
        curY += addY - subY;
        distinct.add(`${curX},${curY}`);
    }
    return distinct.size;
};
